-- Local synthetic tables only. Resolver bodies come unchanged from live read-only audit.
create schema school_category_private;create schema contract_operations_private;
create type rs_content_type as enum('BOOK','PRINTABLE','QUESTION','GAME');
alter table content_items alter column content_type type rs_content_type using content_type::rs_content_type;
alter table content_items add title text,add segment_id uuid,add grade_id uuid,add subject_id uuid,add owner_tenant_id uuid,add owner_user_id uuid;
alter table classes add school_year text,add age_group text;
alter table teachers add created_at timestamptz default now();
alter table students add school_id uuid;
update students set school_id=(select id from schools limit 1);
alter table enrollments add id uuid default gen_random_uuid();
alter table content_segments add name text;
alter table content_grades add name text,add sort_order int;
create table tenants(id uuid primary key,school_id uuid,network_id uuid,tenant_type text,status text,metadata jsonb);
create table contracts(id uuid primary key,tenant_id uuid,status text,starts_at date,ends_at date,metadata jsonb);
create table contract_operations_private.targets(contract_id uuid,school_id uuid,licensed boolean,adoption_on date,cancelled_before_use boolean);
create table network_school_memberships(network_id uuid,school_id uuid,status text,ended_at timestamptz);
create table education_networks(id uuid,status text);
create table tenant_product_entitlements(id uuid primary key,tenant_id uuid,contract_id uuid,product_id uuid,status text,starts_at date,ends_at date,grade_ids uuid[],metadata jsonb);
create table contract_products(contract_id uuid,product_id uuid,status text,metadata jsonb);
create table products(id uuid,status text);
create table product_content_modules(product_id uuid,content_module_id uuid);
create table content_modules(id uuid,name text,status text,content_types rs_content_type[]);
create table tenant_product_content_modules(entitlement_id uuid,content_module_id uuid,enabled boolean);
create table content_access_exceptions(content_item_id uuid,school_id uuid,tenant_id uuid,action text,starts_at timestamptz,ends_at timestamptz);
create table content_subjects(id uuid,status text);
create table content_question_items(content_item_id uuid,question_item_id uuid);
create table question_items(id uuid,publication_status text,curation_status text,license_id uuid,source_id uuid);
create table question_sources(id uuid,license_id uuid);
create table question_licenses(id uuid,publication_allowed boolean);
CREATE OR REPLACE FUNCTION contract_operations_private.in_scope(p_contract uuid, p_school uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO '' AS $$ select exists(select 1 from contract_operations_private.targets where contract_id=p_contract and school_id=p_school and licensed); $$;
CREATE OR REPLACE FUNCTION contract_operations_private.superseded(p_contract uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO '' AS $$ select exists(select 1 from public.contracts successor join contract_operations_private.targets target on target.contract_id=successor.id where successor.metadata->>'source'='contract_operations_v1' and successor.metadata->>'renewal_of'=p_contract::text and target.adoption_on<=(now() at time zone 'America/Sao_Paulo')::date and not target.cancelled_before_use); $$;
